-- Idempotent guarded Phase 3 apply. No business data or grade/result mutation.
SELECT COUNT(DISTINCT table_name) INTO @dependency_count FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name IN ('supplementary_exam_periods','supplementary_exam_period_events','supplementary_exam_offerings','supplementary_exam_offering_sources','supplementary_exam_offering_events','student_course_registrations','registration_statuses','student_course_results','result_statuses','grade_components','student_grade_components','grade_part_approvals','grade_approvals','approval_statuses','grading_policies','users','roles','permissions','role_permissions');
SET @phase2_ready := IF(@dependency_count=19,1,0);
SET @ddl := IF(@phase2_ready=1,'CREATE TABLE IF NOT EXISTS `alrowad_uni_rust`.`supplementary_exam_theoretical_deferrals` (`supplementary_exam_theoretical_deferral_id` INT NOT NULL AUTO_INCREMENT,`supplementary_exam_offering_id` INT NOT NULL,`student_course_registration_id` INT NOT NULL,`status` VARCHAR(16) NOT NULL,`current_slot` TINYINT NULL,`declared_by_user_id` INT NOT NULL,`declared_at` DATETIME NOT NULL,`cancelled_by_user_id` INT NULL,`cancelled_at` DATETIME NULL,`cancellation_reason` TEXT NULL,`superseded_at` DATETIME NULL,`supersede_reason` TEXT NULL,`created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`supplementary_exam_theoretical_deferral_id`),UNIQUE KEY `uq_supp_deferral_identity` (`supplementary_exam_offering_id`,`student_course_registration_id`),UNIQUE KEY `uq_supp_deferral_current` (`student_course_registration_id`,`current_slot`),KEY `ix_supp_deferral_actor` (`declared_by_user_id`),KEY `ix_supp_deferral_cancel_actor` (`cancelled_by_user_id`),CONSTRAINT `fk_supp_deferral_offering` FOREIGN KEY (`supplementary_exam_offering_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_offerings` (`supplementary_exam_offering_id`),CONSTRAINT `fk_supp_deferral_registration` FOREIGN KEY (`student_course_registration_id`) REFERENCES `alrowad_uni_rust`.`student_course_registrations` (`student_course_registration_id`),CONSTRAINT `fk_supp_deferral_declarer` FOREIGN KEY (`declared_by_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`),CONSTRAINT `fk_supp_deferral_canceller` FOREIGN KEY (`cancelled_by_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`)) ENGINE=InnoDB COMMENT=''[phase3-supplementary-exam-eligibility] explicit voluntary theory decisions''','SELECT 0'); PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @ddl := IF(@phase2_ready=1,'CREATE TABLE IF NOT EXISTS `alrowad_uni_rust`.`supplementary_exam_theoretical_deferral_events` (`supplementary_exam_theoretical_deferral_event_id` INT NOT NULL AUTO_INCREMENT,`supplementary_exam_theoretical_deferral_id` INT NOT NULL,`event_type` VARCHAR(16) NOT NULL,`from_status` VARCHAR(16) NULL,`to_status` VARCHAR(16) NOT NULL,`actor_user_id` INT NOT NULL,`notes` TEXT NULL,`created_at` DATETIME NOT NULL,PRIMARY KEY (`supplementary_exam_theoretical_deferral_event_id`),KEY `ix_supp_deferral_event_history` (`supplementary_exam_theoretical_deferral_id`,`created_at`),KEY `ix_supp_deferral_event_actor` (`actor_user_id`),CONSTRAINT `fk_supp_deferral_event_parent` FOREIGN KEY (`supplementary_exam_theoretical_deferral_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_theoretical_deferrals` (`supplementary_exam_theoretical_deferral_id`),CONSTRAINT `fk_supp_deferral_event_actor` FOREIGN KEY (`actor_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`)) ENGINE=InnoDB COMMENT=''[phase3-supplementary-exam-eligibility] immutable deferral audit''','SELECT 0'); PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
INSERT INTO `alrowad_uni_rust`.`permissions` (module_id,permission_code,permission_name,description,is_active,created_at,updated_at) SELECT (SELECT module_id FROM `alrowad_uni_rust`.`system_modules` WHERE module_code='exams' AND is_active=1 LIMIT 1), 'supplementary_exams.eligibility.view','View supplementary eligibility','[phase3-supplementary-exam-eligibility] staff read access',1,NOW(),NOW() WHERE @phase2_ready=1 ON DUPLICATE KEY UPDATE permission_name=VALUES(permission_name),is_active=1;
INSERT INTO `alrowad_uni_rust`.`permissions` (module_id,permission_code,permission_name,description,is_active,created_at,updated_at) SELECT (SELECT module_id FROM `alrowad_uni_rust`.`system_modules` WHERE module_code='exams' AND is_active=1 LIMIT 1), 'supplementary_exams.deferrals.self','Self-declare theoretical deferral','[phase3-supplementary-exam-eligibility] student self service',1,NOW(),NOW() WHERE @phase2_ready=1 ON DUPLICATE KEY UPDATE permission_name=VALUES(permission_name),is_active=1;
INSERT IGNORE INTO `alrowad_uni_rust`.`role_permissions` (role_id,permission_id,granted_at) SELECT r.role_id,p.permission_id,NOW() FROM `alrowad_uni_rust`.`roles` r JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_code='supplementary_exams.eligibility.view' WHERE @phase2_ready=1 AND r.role_code IN ('dean','registration_officer','exam_officer','vice_president_scientific');
INSERT IGNORE INTO `alrowad_uni_rust`.`role_permissions` (role_id,permission_id,granted_at) SELECT r.role_id,p.permission_id,NOW() FROM `alrowad_uni_rust`.`roles` r JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_code='supplementary_exams.deferrals.self' WHERE @phase2_ready=1 AND r.role_code='student';
SELECT 'APPLY_RESULT' AS report_section,IF(@phase2_ready=1,'APPLIED','BLOCKED') AS result,IF(@phase2_ready=1,NULL,'PHASE2_NOT_DEPLOYED') AS blocker_code;
